     1	/**
     2	 * Notification-preference types + helpers. Plain module (safe to import from
     3	 * client and server components; the `"use server"` action file may only export
     4	 * async functions, so these live here).
     5	 *
     6	 * Persisted to `User.notificationPrefs` (Json). Three toggle groups:
     7	 *   - email:    transactional/account email (invoices, deploys)
     8	 *   - product:  product news & announcements
     9	 *   - security: security alerts (new logins, token changes)
    10	 */
    11	export type NotificationPrefs = {
    12	  email: boolean;
    13	  product: boolean;
    14	  security: boolean;
    15	};
    16	
    17	export const DEFAULT_PREFS: NotificationPrefs = { email: true, product: true, security: true };
    18	
    19	/** Normalise whatever is stored in the Json column into a typed prefs object. */
    20	export function normalizePrefs(raw: unknown): NotificationPrefs {
    21	  const p = (raw ?? {}) as Record<string, unknown>;
    22	  return {
    23	    email: typeof p.email === "boolean" ? p.email : DEFAULT_PREFS.email,
    24	    product: typeof p.product === "boolean" ? p.product : DEFAULT_PREFS.product,
    25	    security: typeof p.security === "boolean" ? p.security : DEFAULT_PREFS.security,
    26	  };
    27	}
