     8	/** Save notification preferences from the settings form. */
     9	export async function updateNotificationPrefs(
    10	  prev: unknown,
    11	  formData: FormData,
    12	): Promise<{ ok?: boolean; error?: string }> {
    13	  const user = await requireUser();
    14	  const prefs: NotificationPrefs = {
    15	    email: formData.get("email") === "on",
    16	    product: formData.get("product") === "on",
    17	    security: formData.get("security") === "on",
    18	  };
    19	  await db.user.update({ where: { id: user.id }, data: { notificationPrefs: prefs } });
    20	  revalidatePath("/dashboard/settings");
    21	  return { ok: true };
    22	}
