 11	/**
 12	 * Resolve a user's TOTP secret, preferring the encrypted column and falling back
 13	 * to any legacy plaintext value so already-enrolled users keep working.
 14	 */
 15	function totpSecretOf(user: { totpSecret: string | null; totpSecretEnc: string | null }): string | null {
 16	  return decryptSecret(user.totpSecretEnc) ?? user.totpSecret;
 17	}
 18	
 19	/**
 20	 * Two-factor authentication (TOTP) server actions.
 21	 *
 22	 * Enrolment flow:
 23	 *   1. `beginTotpEnrollment()` -> generates a secret, stores it (totpEnabled
 24	 *      stays false), and returns the otpauth URI + secret for the UI to show.
 25	 *   2. `confirmTotpEnrollment(code)` -> user enters a code from their app; on
 26	 *      success `totpEnabled` flips true and backup codes are generated.
 27	 *   3. `disableTotp(codeOrPassword)` -> requires a valid TOTP/backup code OR
 28	 *      the account password.
 29	 *
 30	 * Backup codes are one-time; only their sha256 hashes are stored.
 31	 */
 32	
 33	function hashCode(code: string): string {
 34	  return createHash("sha256").update(code.trim().toLowerCase()).digest("hex");
 35	}
 36	
 37	/** Generate N human-friendly one-time backup codes (plaintext, for display). */
 38	function makeBackupCodes(n = 10): string[] {
 39	  return Array.from({ length: n }, () => {
 40	    const raw = randomBytes(5).toString("hex"); // 10 hex chars
 41	    return `${raw.slice(0, 5)}-${raw.slice(5)}`;
 42	  });
 43	}
