 45	/**
 46	 * Verify a submitted code for a user: passes if it matches TOTP OR consumes a
 47	 * valid one-time backup code (which is then removed). Intended to be called by
 48	 * the login flow once the password check succeeds.
 49	 */
 50	export async function verifyTotpForUser(userId: string, code: string): Promise<boolean> {
 51	  const user = await db.user.findUnique({ where: { id: userId } });
 52	  if (!user || !user.totpEnabled) return false;
 53	  const secret = totpSecretOf(user);
 54	  if (!secret) return false;
 55	
 56	  if (verifyTOTP(secret, code)) return true;
 57	
 58	  // Fall back to consuming a backup code.
 59	  const submitted = hashCode(code);
 60	  const idx = user.backupCodes.indexOf(submitted);
 61	  if (idx === -1) return false;
 62	  const remaining = user.backupCodes.filter((_, i) => i !== idx);
 63	  await db.user.update({ where: { id: user.id }, data: { backupCodes: remaining } });
 64	  await db.auditLog.create({ data: { userId: user.id, action: "user.2fa_backup_code_used" } });
 65	  return true;
 66	}
 67	
 68	/**
 69	 * Step 1: create (but do not yet activate) a TOTP secret.
 70	 *
 71	 * Return shape keeps `secret`/`otpauthUrl` present (empty on refusal) so the
 72	 * existing typed caller (`useState<{secret;otpauthUrl}>`) still compiles; an
 73	 * optional `error` is populated when enrolment is refused.
 74	 */
 75	export async function beginTotpEnrollment(): Promise<{ secret: string; otpauthUrl: string; error?: string }> {
 76	  const user = await requireUser();
 77	
 78	  // Block enrolment while impersonating: the real acting account must be the
 79	  // same account being enrolled, so an admin can't seed a customer's 2FA.
 80	  const real = await realUser();
 81	  if (!real || real.id !== user.id) {
 82	    return { secret: "", otpauthUrl: "", error: "You can't set up 2FA while impersonating another account." };
 83	  }
 84	
 85	  // Refuse to overwrite an ALREADY-ACTIVE secret — doing so silently disabled
 86	  // the user's working 2FA (totpEnabled=false + fresh secret) with no re-auth.
 87	  if (user.totpEnabled === true) {
 88	    return { secret: "", otpauthUrl: "", error: "Disable your current 2FA first." };
 89	  }
 90	
 91	  const secret = generateSecret();
 92	  // Store encrypted at rest; clear any legacy plaintext value for this account.
 93	  await db.user.update({
 94	    where: { id: user.id },
 95	    data: { totpSecretEnc: encryptSecret(secret), totpSecret: null, totpEnabled: false },
 96	  });
 97	  return { secret, otpauthUrl: otpauthURL(secret, user.email) };
 98	}
