100	/** Step 2: confirm enrolment with a code; activates 2FA and returns backup codes. */
101	export async function confirmTotpEnrollment(
102	  prev: unknown,
103	  formData: FormData,
104	): Promise<{ error?: string; ok?: boolean; backupCodes?: string[] }> {
105	  const user = await requireUser();
106	  const code = String(formData.get("code") ?? "");
107	  const secret = totpSecretOf(user);
108	  if (!secret) return { error: "Start enrolment first." };
109	  if (!verifyTOTP(secret, code)) return { error: "That code is incorrect. Try again." };
110	
111	  const backupCodes = makeBackupCodes();
112	  await db.user.update({
113	    where: { id: user.id },
114	    data: { totpEnabled: true, backupCodes: backupCodes.map(hashCode) },
115	  });
116	  await db.auditLog.create({ data: { userId: user.id, action: "user.2fa_enabled" } });
117	  revalidatePath("/dashboard/settings");
118	  return { ok: true, backupCodes };
119	}
