121	/** Regenerate backup codes (invalidates any previous ones). Requires a valid TOTP code. */
122	export async function regenerateBackupCodes(
123	  prev: unknown,
124	  formData: FormData,
125	): Promise<{ error?: string; backupCodes?: string[] }> {
126	  const user = await requireUser();
127	  const code = String(formData.get("code") ?? "");
128	  const secret = totpSecretOf(user);
129	  if (!user.totpEnabled || !secret) return { error: "2FA is not enabled." };
130	  if (!verifyTOTP(secret, code)) return { error: "That code is incorrect." };
131	  const backupCodes = makeBackupCodes();
132	  await db.user.update({ where: { id: user.id }, data: { backupCodes: backupCodes.map(hashCode) } });
133	  await db.auditLog.create({ data: { userId: user.id, action: "user.2fa_backup_regenerated" } });
134	  return { backupCodes };
135	}
136	
137	/** Disable 2FA. Requires a valid TOTP/backup code OR the account password. */
138	export async function disableTotp(
139	  prev: unknown,
140	  formData: FormData,
141	): Promise<{ error?: string; ok?: boolean }> {
142	  const user = await requireUser();
143	  const proof = String(formData.get("proof") ?? "");
144	  if (!user.totpEnabled) return { error: "2FA is not enabled." };
145	
146	  const secret = totpSecretOf(user);
147	  const codeValid =
148	    (secret ? verifyTOTP(secret, proof) : false) ||
149	    (await verifyTotpForUser(user.id, proof));
150	  const passwordValid = proof.length > 0 && (await bcrypt.compare(proof, user.passwordHash));
151	  if (!codeValid && !passwordValid) {
152	    return { error: "Enter a valid authenticator code, backup code, or your password." };
153	  }
154	
155	  await db.user.update({
156	    where: { id: user.id },
157	    data: { totpEnabled: false, totpSecret: null, totpSecretEnc: null, backupCodes: [] },
158	  });
159	  await db.auditLog.create({ data: { userId: user.id, action: "user.2fa_disabled" } });
160	  revalidatePath("/dashboard/settings");
161	  return { ok: true };
162	}

