136	export async function resetPassword(prev: any, formData: FormData): Promise<{ error?: string; ok?: boolean }> {
137	  const token = String(formData.get("token") ?? "");
138	  const password = String(formData.get("password") ?? "");
139	  if (password.length < 8) return { error: "Password must be at least 8 characters." };
140	  const { createHash } = await import("node:crypto");
141	  const tokenHash = createHash("sha256").update(token).digest("hex");
142	  const row = await db.passwordResetToken.findUnique({ where: { tokenHash } });
143	  if (!row || row.usedAt || row.expiresAt < new Date()) {
144	    return { error: "This reset link is invalid or has expired. Request a new one." };
145	  }
146	  await db.$transaction([
147	    // Bump sessionVersion so any sessions predating the reset are evicted.
148	    db.user.update({
149	      where: { id: row.userId },
150	      data: { passwordHash: await bcrypt.hash(password, 12), sessionVersion: { increment: 1 } },
151	    }),
152	    db.passwordResetToken.update({ where: { id: row.id }, data: { usedAt: new Date() } }),
153	    db.auditLog.create({ data: { userId: row.userId, action: "user.password_reset_complete" } }),
154	  ]);
155	  return { ok: true };
156	}
