 3	import { useState, useTransition } from "react";
 4	import { DASHBOARD_AREAS } from "@/lib/team-areas";
 5	import { setMemberAreas } from "@/lib/actions-teams";
 6	
 7	/**
 8	 * Per-member dashboard-area editor. Renders one toggle per assignable area and
 9	 * persists changes through the `setMemberAreas` server action. `initialAreas`
10	 * of null means the member currently has full (role-default) access, shown here
11	 * as every box checked; unchecking any box switches them to an explicit list.
12	 */
13	export default function MemberAreas({
14	  membershipId,
15	  initialAreas,
16	}: {
17	  membershipId: string;
18	  initialAreas: string[] | null;
19	}) {
20	  const [selected, setSelected] = useState<Set<string>>(
21	    () => new Set(initialAreas ?? DASHBOARD_AREAS.map((a) => a.key)),
22	  );
23	  const [restricted, setRestricted] = useState<boolean>(initialAreas !== null);
24	  const [pending, start] = useTransition();
25	  const [msg, setMsg] = useState<{ tone: "error" | "ok"; text: string } | null>(null);
26	
27	  function persist(next: Set<string>) {
28	    setMsg(null);
29	    start(async () => {
30	      const res = await setMemberAreas(membershipId, [...next]);
31	      if (res.error) setMsg({ tone: "error", text: res.error });
32	      else {
33	        setRestricted(true);
34	        setMsg({ tone: "ok", text: "Access updated." });
35	      }
36	    });
37	  }
38	
39	  function toggle(key: string, on: boolean) {
40	    const next = new Set(selected);
41	    if (on) next.add(key);
42	    else next.delete(key);
43	    setSelected(next);
44	    persist(next);
45	  }
46	
47	  return (
48	    <div className="space-y-2">
49	      <div className="flex items-center gap-2">
50	        <span className="text-xs font-medium text-slate-300">Dashboard access</span>
51	        {!restricted && (
52	          <span className="text-[11px] text-slate-500">full access (role default)</span>
53	        )}
54	      </div>
55	      <div className="flex flex-wrap gap-x-4 gap-y-1.5">
56	        {DASHBOARD_AREAS.map((a) => (
57	          <label
58	            key={a.key}
59	            className="flex items-center gap-1.5 text-xs text-slate-300"
60	          >
61	            <input
62	              type="checkbox"
63	              className="accent-brand-500"
64	              checked={selected.has(a.key)}
65	              disabled={pending}
66	              onChange={(e) => toggle(a.key, e.target.checked)}
67	            />
68	            {a.label}
69	          </label>
70	        ))}
71	      </div>
72	      {msg && (
73	        <span
74	          className={`text-[11px] ${msg.tone === "error" ? "text-red-400" : "text-emerald-400"}`}
75	        >
76	          {msg.text}
77	        </span>
78	      )}
79	    </div>
80	  );
81	}

