 61	export default async function DashboardLayout({ children }: { children: React.ReactNode }) {
 62	  const user = await currentUser();
 63	  if (!user) redirect("/login");
 64	  const imp = await impersonating();
 65	
 66	  // Maintenance mode: gate the whole customer portal for non-admins. Admins (and
 67	  // admins impersonating a customer) always pass so they can keep working. This
 68	  // only covers the dashboard tree — /login and /admin have their own layouts.
 69	  if (user.role !== "ADMIN" && (await getSettingBool("maintenance_mode", false))) {
 70	    const message = await getSetting("maintenance_message");
 71	    return (
 72	      <main
 73	        style={{
 74	          minHeight: "100vh",
 75	          display: "flex",
 76	          flexDirection: "column",
 77	          alignItems: "center",
