 79	          gap: "1rem",
 80	          padding: "2rem",
 81	          textAlign: "center",
 82	        }}
 83	      >
 84	        <h1 style={{ fontSize: "1.5rem", fontWeight: 600 }}>Down for maintenance</h1>
 85	        <p style={{ maxWidth: "32rem", opacity: 0.8 }}>{message}</p>
 86	      </main>
 87	    );
 88	  }
 89	
 90	  // Hide nav entries whose feature flag is disabled (secondary to the server-side
 91	  // refusals in the order/create actions).
 92	  const flags: Record<string, boolean> = {
 93	    feature_game_servers: await getSettingBool("feature_game_servers", true),
 94	    feature_claude_builder: await getSettingBool("feature_claude_builder", true),
 95	    feature_domains: await getSettingBool("feature_domains", true),
 96	    feature_referrals: await getSettingBool("feature_referrals", true),
 97	  };
 98	  const visibleNav: NavSection[] = nav
 99	    .map((section) => ({
100	      ...section,
101	      items: section.items.filter((item) => {
102	        const flag = FEATURE_HREF[item.href];
103	        return !flag || flags[flag];
104	      }),
105	    }))
106	    .filter((section) => section.items.length > 0);
107	
108	  const notifications = await db.notification.findMany({
109	    where: { userId: user.id },
110	    orderBy: { createdAt: "desc" },
111	    take: 15,
112	  });
113	
114	  // Support badge: this customer's own tickets awaiting a staff reply
115	  // (their newly opened tickets + threads where they replied last). Fails soft.
116	  const supportAwaiting = await db.ticket
117	    .count({ where: { userId: user.id, status: { in: ["OPEN", "CUSTOMER_REPLY"] } } })
118	    .catch(() => 0);
119	  const navWithBadges: NavSection[] = visibleNav.map((section) => ({
120	    ...section,
121	    items: section.items.map((item) =>
122	      item.href === "/dashboard/support" && supportAwaiting > 0
123	        ? { ...item, badge: supportAwaiting }
124	        : item
125	    ),
126	  }));
127	
128	  return (
129	    <Shell
130	      nav={navWithBadges}
131	      user={{ name: user.name, email: user.email, role: user.role, balanceCents: user.balanceCents }}
132	      notifications={notifications.map((n) => ({
