136	        href: n.href,
137	        readAt: n.readAt ? n.readAt.toISOString() : null,
138	        createdAt: n.createdAt.toISOString(),
139	      }))}
140	      impersonation={imp ? { adminName: imp.admin.name, targetEmail: imp.target.email } : null}
141	    >
142	      {children}
143	    </Shell>
144	  );
145	}

