 98	    setError(null);
 99	    startTransition(async () => {
100	      const res = await approveBuild(buildId);
101	      if (res.error) {
102	        setError(res.error);
103	        return;
104	      }
105	      // Optimistically flip to QUEUED; polling will pick up RUNNING → DONE.
106	      setState((s) => (s ? { ...s, status: "QUEUED" } : s));
107	    });
108	  };
109	
110	  const onReject = () => {
111	    if (!buildId) return;
112	    setError(null);
113	    startTransition(async () => {
114	      const res = await rejectBuild(buildId);
115	      if (res.error) {
116	        setError(res.error);
117	        return;
118	      }
119	      setState((s) => (s ? { ...s, status: "FAILED" } : s));
120	    });
121	  };
122	
123	  const reset = () => {
124	    setBuildId(null);
125	    setState(null);
126	    setPrompt("");
127	    setError(null);
128	  };
129	
