  1	// "Build with Claude AI" worker handler — SAFE, plan-then-approve.
  2	//
  3	// Two phases, driven by ClaudeBuild.approved:
  4	//   1. PLAN  (approved=false): ask Claude — with the OWNER'S effective key — for
  5	//      an ordered JSON array of non-destructive shell commands. Store it to
  6	//      ClaudeBuild.plan and set AWAITING_APPROVAL. NOTHING is executed.
  7	//   2. EXECUTE (approved=true): run each approved command over SSH, enforcing a
  8	//      denylist, a per-command timeout, and a hard command cap. Append output to
  9	//      ClaudeBuild.log, then set DONE (or FAILED on error). Never runs a command
 10	//      that was not part of the approved plan.
 11	//
 12	// This handler is wired into worker/index.ts's `handlers` map by the
 13	// orchestrator (see INTEGRATION NEEDED in the final report):
 14	//   import { claudeBuild } from "./claude";
 15	//   CLAUDE_BUILD: claudeBuild,
 16	
 17	import { execFile } from "node:child_process";
 18	import { promisify } from "node:util";
 19	import { db } from "../lib/db";
 20	import { askClaude, effectiveKeyFor, type ClaudeMessage } from "../lib/anthropic";
 21	import { SANDBOX } from "../lib/sandbox";
 22	import { serverRootPassword } from "../lib/sftp";
 23	import type { Job } from "@prisma/client";
 24	
 25	const execFileAsync = promisify(execFile);
 26	
 27	/** Hard cap on the number of commands executed for a single build. */
 28	export const CLAUDE_MAX_COMMANDS = 20;
 29	
 30	/** Per-command SSH execution timeout. */
 31	const CMD_TIMEOUT_MS = 120_000;
 32	/** Cap on captured output per command (chars) to keep the log bounded. */
 33	const MAX_OUTPUT_CHARS = 4000;
 34	/** Cap on total stored log size. */
 35	const MAX_LOG_CHARS = 60_000;
 36	
 37	type PlanStep = { cmd: string; intent: string };
 38	
 39	const PLAN_SYSTEM_PROMPT = `You are an expert Linux server administrator. You are given a goal for a SINGLE Debian/Ubuntu server that you operate on over SSH as root. Produce a PLAN — do NOT run anything.
 40	
 41	Output ONLY a JSON array of steps and NOTHING else (no markdown, no backticks, no prose before or after). Each step is an object:
 42	{"cmd": "<one non-interactive shell command>", "intent": "<short plain-English explanation of what it does and why>"}
 43	
 44	Rules for the plan:
 45	- Operate ONLY on this one server. Never touch other hosts, networks, or cloud APIs.
 46	- Commands must be non-interactive: use flags like -y and DEBIAN_FRONTEND=noninteractive; never launch editors, pagers, REPLs, or anything that waits for input.
 47	- NON-DESTRUCTIVE ONLY. Absolutely no whole-disk or whole-system operations: no rm -rf /, no mkfs/fdisk/dd on disks, no wiping /etc, no reboot/shutdown/poweroff/halt, no user/password changes, no disabling SSH.
 48	- Keep each command self-contained and idempotent where possible.
 49	- Prefer standard packages and services (apt, systemctl, nginx, ufw, etc.).
 50	- At most ${CLAUDE_MAX_COMMANDS} steps. If the goal cannot be met safely, return an empty array [].`;
 51	
 52	/** Escape a string for safe single-quoted inclusion in a bash -c argument. */
 53	function shSingleQuote(s: string): string {
 54	  return `'${s.replace(/'/g, `'\\''`)}'`;
 55	}
 56	
 57	/** Reject catastrophic commands as a defense-in-depth backstop (denylist). */
 58	function isForbidden(cmd: string): boolean {
 59	  const c = cmd.toLowerCase();
 60	  const patterns = [
 61	    /rm\s+(-[a-z]*\s+)*(-[a-z]*r[a-z]*f|-[a-z]*f[a-z]*r)\s+\/(\s|$)/, // rm -rf /
 62	    /\bmkfs\b/,
 63	    /\bfdisk\b/,
 64	    /\bparted\b/,
 65	    /\bdd\b[^|]*of=\/dev\//, // dd of=/dev/*
 66	    /\b(reboot|shutdown|poweroff|halt|init\s+0|init\s+6)\b/,
 67	    /\bshred\b/,
 68	    /\bpasswd\b/,
 69	    /:\(\)\s*\{.*\};:/, // fork bomb :(){ :|:& };:
 70	    />\s*\/dev\/sd[a-z]/,
 71	    /\bsystemctl\s+(stop|disable|mask)\s+(ssh|sshd)\b/,
 72	  ];
 73	  return patterns.some((p) => p.test(c));
 74	}
 75	
 76	/** Run one command on the server over SSH via sshpass. Never throws. */
 77	async function sshExec(
 78	  server: { ipAddress: string | null; rootPassword: string | null; rootPasswordEnc?: string | null },
 79	  command: string
 80	): Promise<{ output: string; failed: boolean }> {
 81	  const password = serverRootPassword(server);
 82	  if (!server.ipAddress || !password) {
 83	    return { output: "[nxeon] server has no reachable IP or root password", failed: true };
 84	  }
 85	  // The worker reaches VMs directly on the private bridge (10.20.0.0/24), so we
 86	  // connect to the private IP on port 22.
 87	  const args = [
 88	    "-p",
 89	    password,
 90	    "ssh",
 91	    "-o",
 92	    "StrictHostKeyChecking=no",
 93	    "-o",
 94	    "UserKnownHostsFile=/dev/null",
 95	    "-o",
 96	    "ConnectTimeout=10",
 97	    "-o",
 98	    "BatchMode=no",
 99	    `root@${server.ipAddress}`,
100	    // Wrap in bash -c with a single-quoted payload so complex commands survive intact.
101	    `bash -c ${shSingleQuote(command)}`,
102	  ];
103	  try {
104	    const { stdout, stderr } = await execFileAsync("sshpass", args, {
105	      timeout: CMD_TIMEOUT_MS,
106	      maxBuffer: 8 * 1024 * 1024,
107	      env: { ...process.env, DEBIAN_FRONTEND: "noninteractive" },
108	    });
109	    const out = `${stdout}${stderr ? `\n${stderr}` : ""}`.trim();
110	    return { output: out || "[no output]", failed: false };
111	  } catch (e: any) {
112	    // execFile rejects on non-zero exit or timeout; capture whatever we got.
113	    const out = `${e?.stdout ?? ""}${e?.stderr ? `\n${e.stderr}` : ""}`.trim();
114	    const reason = e?.killed
115	      ? `[nxeon] command timed out after ${CMD_TIMEOUT_MS / 1000}s`
116	      : `[nxeon] command exited with code ${e?.code ?? "?"}`;
117	    return { output: `${out ? out + "\n" : ""}${reason}`, failed: true };
118	  }
119	}
120	
121	function truncate(s: string, max: number): string {
122	  return s.length > max ? s.slice(0, max) + "\n…[truncated]" : s;
123	}
124	
125	/** Parse Claude's plan reply into a validated list of steps, or null. */
126	function parsePlan(reply: string): PlanStep[] | null {
127	  const start = reply.indexOf("[");
128	  const end = reply.lastIndexOf("]");
129	  if (start === -1 || end === -1 || end < start) return null;
130	  let raw: unknown;
131	  try {
132	    raw = JSON.parse(reply.slice(start, end + 1));
133	  } catch {
134	    return null;
135	  }
136	  if (!Array.isArray(raw)) return null;
137	  const steps: PlanStep[] = [];
138	  for (const item of raw) {
139	    if (typeof item === "string") {
140	      const cmd = item.trim();
141	      if (cmd) steps.push({ cmd, intent: "" });
142	    } else if (item && typeof item === "object") {
143	      const anyItem = item as Record<string, unknown>;
144	      const cmd = String(anyItem.cmd ?? anyItem.command ?? "").trim();
145	      const intent = String(anyItem.intent ?? anyItem.description ?? "").trim();
146	      if (cmd) steps.push({ cmd, intent });
147	    }
148	  }
149	  return steps.length ? steps : null;
150	}
