152	async function failBuild(buildId: string, priorLog: string, note: string): Promise<void> {
153	  await db.claudeBuild.update({
154	    where: { id: buildId },
155	    data: { status: "FAILED", log: truncate(priorLog + `\n[nxeon] ${note}\n`, MAX_LOG_CHARS) },
156	  });
157	}
