159	export async function claudeBuild(job: Job): Promise<void> {
160	  const payload = (job.payload ?? {}) as { buildId?: string };
161	  const buildId = payload.buildId;
162	  if (!buildId) throw new Error("claudeBuild: missing buildId in job payload");
163	
164	  const build = await db.claudeBuild.findUnique({ where: { id: buildId }, include: { server: true } });
165	  if (!build) throw new Error(`claudeBuild: build ${buildId} not found`);
166	  const server = build.server;
167	
168	  // Terminal builds are never re-processed by a stray/duplicate job.
169	  if (build.status === "DONE" || build.status === "FAILED") return;
170	
171	  if (SANDBOX) {
172	    // Simulate the plan-then-approve flow with no Anthropic call and no SSH.
173	    if (!build.approved) {
174	      await db.claudeBuild.update({
175	        where: { id: buildId },
176	        data: {
177	          status: "AWAITING_APPROVAL",
178	          plan: JSON.stringify([{ cmd: "echo sandbox build", intent: "Sandbox simulated step" }]),
179	        },
180	      });
181	    } else {
182	      await db.claudeBuild.update({
183	        where: { id: buildId },
184	        data: {
185	          status: "DONE",
186	          steps: 1,
187	          log: truncate((build.log ?? "") + "\n[sandbox] simulated build completed\n", MAX_LOG_CHARS),
188	        },
189	      });
190	      await db.notification
191	        .create({
192	          data: {
193	            userId: build.userId,
194	            title: `Claude finished building on ${server?.hostname ?? "your server"}`,
195	            body: build.prompt.slice(0, 140),
196	            href: `/dashboard/build`,
197	          },
198	        })
199	        .catch(() => {});
200	    }
201	    return;
202	  }
203	
204	  // Everything is gated on an effective owner key + a reachable RUNNING server.
205	  const owner = await db.user.findUnique({
206	    where: { id: build.userId },
207	    select: { anthropicKeyEnc: true },
208	  });
209	  const apiKey = effectiveKeyFor(owner);
210	  if (!apiKey) {
211	    await failBuild(buildId, build.log ?? "", "No Anthropic API key available for the owner.");
212	    return;
213	  }
214	  if (!server || server.status !== "RUNNING") {
215	    await failBuild(buildId, build.log ?? "", "The server is not running.");
216	    return;
217	  }
218	  if (!server.ipAddress || !serverRootPassword(server)) {
219	    await failBuild(buildId, build.log ?? "", "The server is not reachable (no IP or root password).");
220	    return;
221	  }
222	
223	  if (!build.approved) {
224	    await planPhase(buildId, build.status, build.prompt, build.log ?? "", apiKey);
225	  } else {
226	    await executePhase(buildId, build.prompt, build.plan, build.log ?? "", server);
227	  }
228	}
229	
230	/** Phase 1: ask Claude for a plan, store it, and await owner approval. */
231	async function planPhase(
232	  buildId: string,
233	  status: string,
234	  prompt: string,
235	  priorLog: string,
236	  apiKey: string
237	): Promise<void> {
238	  // Only plan for a not-yet-planned build; ignore duplicate jobs otherwise.
239	  if (status !== "QUEUED" && status !== "PLANNING") return;
240	
241	  await db.claudeBuild.update({ where: { id: buildId }, data: { status: "PLANNING" } });
242	
243	  const messages: ClaudeMessage[] = [
244	    { role: "user", content: `Goal: ${prompt}\n\nProduce the plan now as a JSON array of {"cmd","intent"} steps.` },
245	  ];
246	
247	  let reply: string;
248	  try {
249	    reply = await askClaude(apiKey, messages, PLAN_SYSTEM_PROMPT, { maxTokens: 4096, timeoutMs: 90_000 });
250	  } catch (e: any) {
251	    await failBuild(buildId, priorLog, `Planning failed: ${e?.message ?? e}`);
252	    return;
253	  }
254	
255	  const plan = parsePlan(reply);
256	  if (!plan) {
257	    await failBuild(buildId, priorLog, "Claude did not return a usable plan for this goal.");
258	    return;
259	  }
260	
261	  const capped = plan.slice(0, CLAUDE_MAX_COMMANDS);
262	  await db.claudeBuild.update({
263	    where: { id: buildId },
264	    data: { status: "AWAITING_APPROVAL", plan: JSON.stringify(capped) },
265	  });
266	}
267	
268	/** Phase 2: execute the OWNER-APPROVED plan over SSH. */
269	async function executePhase(
270	  buildId: string,
271	  prompt: string,
272	  planJson: string | null,
273	  priorLog: string,
274	  server: { ipAddress: string | null; rootPassword: string | null; rootPasswordEnc?: string | null; hostname: string | null }
275	): Promise<void> {
276	  let plan: PlanStep[] = [];
277	  try {
278	    const parsed = JSON.parse(planJson ?? "[]");
279	    if (Array.isArray(parsed)) {
280	      plan = parsed
281	        .map((s: any) => ({ cmd: String(s?.cmd ?? s ?? "").trim(), intent: String(s?.intent ?? "") }))
282	        .filter((s: PlanStep) => s.cmd);
283	    }
284	  } catch {
285	    plan = [];
286	  }
287	
288	  if (plan.length === 0) {
289	    await failBuild(buildId, priorLog, "No approved plan to execute.");
290	    return;
291	  }
292	
293	  await db.claudeBuild.update({ where: { id: buildId }, data: { status: "RUNNING" } });
294	
295	  const commands = plan.slice(0, CLAUDE_MAX_COMMANDS);
296	  let log = priorLog;
297	  const append = async (chunk: string, steps: number) => {
298	    log = truncate(log + chunk, MAX_LOG_CHARS);
299	    await db.claudeBuild.update({ where: { id: buildId }, data: { log, steps } });
300	  };
301	
302	  await append(`# Goal: ${prompt}\n# Executing approved plan (${commands.length} command(s))\n\n`, 0);
303	
304	  let steps = 0;
305	  let finalStatus: "DONE" | "FAILED" = "DONE";
306	
307	  try {
308	    for (const step of commands) {
309	      const command = step.cmd;
310	
311	      // Defense-in-depth: even an approved plan is re-checked against the denylist.
312	      if (isForbidden(command)) {
313	        await append(`\n$ ${command}\n[nxeon] Skipped — blocked by the safety denylist.\n`, steps);
314	        continue;
315	      }
316	
317	      steps += 1;
318	      const { output, failed } = await sshExec(server, command);
319	      const shown = truncate(output, MAX_OUTPUT_CHARS);
320	      await append(`\n$ ${command}\n${shown}\n`, steps);
321	
322	      if (failed) {
323	        await append(`\n[nxeon] Command failed — stopping execution.\n`, steps);
324	        finalStatus = "FAILED";
325	        break;
326	      }
327	    }
328	  } catch (e: any) {
329	    await append(`\n[nxeon] Build error: ${e?.message ?? e}\n`, steps);
330	    finalStatus = "FAILED";
331	  }
332	
333	  await db.claudeBuild.update({ where: { id: buildId }, data: { status: finalStatus, steps } });
334	
335	  try {
336	    await db.notification.create({
337	      data: {
338	        userId: (await db.claudeBuild.findUnique({ where: { id: buildId }, select: { userId: true } }))!.userId,
339	        title:
340	          finalStatus === "DONE"
341	            ? `Claude finished building on ${server.hostname}`
342	            : `Claude build failed on ${server.hostname}`,
343	        body: prompt.slice(0, 140),
344	        href: `/dashboard/build`,
345	      },
346	    });
347	  } catch {
348	    /* notification is best-effort */
349	  }
350	}

