 16	/**
 17	 * Portal-wide, PERSISTENT terminal dock.
 18	 *
 19	 * The whole point of this component is that it is mounted ONCE, at the portal
 20	 * shell level (components/portal/Shell.tsx). Because the App Router keeps Shell
 21	 * mounted across in-portal navigation, the dock — and every live shell session
 22	 * it holds — survives page changes. Navigating from /dashboard/servers/x to
 23	 * /dashboard/build never unmounts the websocket, so a running `claude` build
 24	 * keeps going.
 25	 *
 26	 * How sessions survive re-renders / route changes / minimize↔restore:
 27	 *   - The tab bar is driven by `sessions` state (plain metadata: id, hostname,
 28	 *     status) so the UI re-renders normally.
 29	 *   - The LIVE objects for each session — the xterm `Terminal`, its `FitAddon`,
 30	 *     the `WebSocket`, the `ResizeObserver`, and a PERSISTENT container <div> —
 31	 *     live in a `Map` ref (`liveRef`). Refs are never recreated by React, so
 32	 *     these objects (and the socket) outlive every render.
 33	 *   - Each session's xterm is attached to its own persistent container div
 34	 *     (created once, stored in the ref). The dock renders one mount slot per
 35	 *     session and appends that same div into it via a ref callback. Switching
 36	 *     the active tab just toggles `display`; the hidden sessions keep their
 37	 *     sockets open in the background. Toggling maximize↔minimize only changes
 38	 *     the OUTER wrapper's size/position classes — the surface holding the
 39	 *     containers keeps the same DOM nodes, so xterm/scrollback/socket are never
 40	 *     recreated.
 41	 *
 42	 * Wire protocol + connection logic are reused verbatim from the old
 43	 * components/customer/WebTerminal.tsx (token → wss /terminal-ws → JSON
 44	 * {type:"data"|"resize"} up, raw output down).
 45	 */
 46	
 47	export type TerminalServerRef = { id: string; hostname: string };
 48	
 49	type Status = "connecting" | "connected" | "closed" | "error";
 50	type Mode = "hidden" | "maximized" | "minimized";
 51	
 52	type SessionMeta = { id: string; hostname: string; status: Status };
 53	
 54	type LiveSession = {
 55	  id: string;
 56	  hostname: string;
 57	  container: HTMLDivElement;
 58	  term: XTerm | null;
 59	  fit: XFitAddon | null;
 60	  ws: WebSocket | null;
 61	  ro: ResizeObserver | null;
 62	  starting: boolean;
 63	};
 64	
 65	type DockApi = {
 66	  openSession: (server: TerminalServerRef) => void;
 67	  focusSession: (id: string) => void;
 68	  closeSession: (id: string) => void;
 69	  minimize: () => void;
 70	  restore: () => void;
 71	  close: () => void;
 72	};
 73	
 74	const DockContext = createContext<DockApi | null>(null);
 75	
 76	/** Hook exposing the dock controls to any client component inside Shell. */
 77	export function useTerminalDock(): DockApi {
 78	  const ctx = useContext(DockContext);
 79	  if (!ctx) throw new Error("useTerminalDock must be used within <TerminalDockProvider>");
 80	  return ctx;
 81	}
