400	/* -------------------------------------------------------------------------- */
401	/* Dock UI                                                                     */
402	/* -------------------------------------------------------------------------- */
403	
404	const STATUS_COLOR: Record<Status, string> = {
405	  connecting: "bg-amber-400 animate-pulse",
406	  connected: "bg-emerald-400",
407	  closed: "bg-slate-500",
408	  error: "bg-red-500",
409	};
410	
411	function IconBtn({
412	  onClick,
413	  label,
414	  children,
415	}: {
416	  onClick: () => void;
417	  label: string;
418	  children: React.ReactNode;
419	}) {
420	  return (
421	    <button
422	      onClick={onClick}
423	      aria-label={label}
424	      title={label}
425	      className="rounded-lg p-1.5 text-slate-400 transition-colors hover:bg-white/10 hover:text-white"
426	    >
427	      {children}
428	    </button>
429	  );
430	}
431	
432	function TerminalDock({
433	  sessions,
434	  activeId,
435	  mode,
436	  errors,
437	  attach,
438	  focusSession,
439	  closeSession,
440	  openSession,
441	  minimize,
442	  restore,
443	  close,
444	  reconnect,
445	}: {
446	  sessions: SessionMeta[];
447	  activeId: string | null;
448	  mode: Mode;
449	  errors: Record<string, string>;
450	  attach: (id: string, el: HTMLDivElement | null) => void;
451	  focusSession: (id: string) => void;
452	  closeSession: (id: string) => void;
453	  openSession: (server: TerminalServerRef) => void;
454	  minimize: () => void;
455	  restore: () => void;
456	  close: () => void;
457	  reconnect: (id: string) => void;
458	}) {
459	  const [pickerOpen, setPickerOpen] = useState(false);
460	  const [pickerLoading, setPickerLoading] = useState(false);
461	  const [pickerServers, setPickerServers] = useState<TerminalServerRef[]>([]);
462	  const [pickerError, setPickerError] = useState<string | null>(null);
463	  const minimized = mode === "minimized";
464	
465	  const activeMeta = sessions.find((s) => s.id === activeId) ?? null;
466	
467	  const loadPicker = useCallback(async () => {
468	    setPickerLoading(true);
469	    setPickerError(null);
470	    try {
471	      const all = await listTerminalServers();
472	      setPickerServers(all);
473	    } catch {
474	      setPickerError("Could not load your servers.");
475	    } finally {
476	      setPickerLoading(false);
477	    }
478	  }, []);
479	
480	  function togglePicker() {
481	    setPickerOpen((v) => {
482	      const next = !v;
483	      if (next) void loadPicker();
484	      return next;
485	    });
486	  }
487	
488	  // Servers not already open as tabs.
489	  const openIds = new Set(sessions.map((s) => s.id));
490	  const pickable = pickerServers.filter((s) => !openIds.has(s.id));
491	
492	  if (mode === "hidden" || sessions.length === 0) return null;
493	
494	  const outerClass = minimized
495	    ? "fixed bottom-4 left-1/2 z-[65] flex h-[280px] w-[460px] max-w-[92vw] -translate-x-1/2 flex-col overflow-hidden rounded-2xl border border-white/10 bg-navy-900 shadow-2xl shadow-black/50"
496	    : "fixed inset-x-0 bottom-0 z-[70] flex h-[70vh] max-h-[82vh] flex-col overflow-hidden border-t border-white/10 bg-navy-900 shadow-2xl shadow-black/50 lg:left-60 lg:rounded-t-2xl lg:border-l";
497	
498	  return (
499	    <div className={outerClass} role="dialog" aria-label="Terminal dock">
500	      {/* Header + tab bar */}
501	      <div className="flex flex-none items-center gap-1.5 border-b border-white/[0.06] bg-white/[0.02] px-2 py-1.5">
502	        {/* Tabs */}
503	        <div className="flex min-w-0 flex-1 items-center gap-1 overflow-x-auto">
504	          {sessions.map((s) => {
505	            const active = s.id === activeId;
506	            return (
507	              <div
508	                key={s.id}
509	                className={`group flex flex-none items-center gap-1.5 rounded-lg border px-2.5 py-1.5 text-xs transition-colors ${
510	                  active
511	                    ? "border-white/15 bg-white/10 text-white"
512	                    : "border-transparent bg-transparent text-slate-400 hover:bg-white/[0.06] hover:text-slate-200"
513	                }`}
514	              >
515	                <button
516	                  onClick={() => focusSession(s.id)}
517	                  className="flex min-w-0 items-center gap-1.5"
518	                  title={s.hostname}
519	                >
520	                  <span className={`h-2 w-2 flex-none rounded-full ${STATUS_COLOR[s.status]}`} />
521	                  <span className="max-w-[8rem] truncate font-medium">{s.hostname}</span>
522	                </button>
523	                <button
524	                  onClick={() => closeSession(s.id)}
525	                  aria-label={`Close ${s.hostname}`}
526	                  className="flex-none rounded p-0.5 text-slate-500 hover:bg-white/10 hover:text-white"
527	                >
528	                  <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round">
529	                    <path d="M18 6 6 18M6 6l12 12" />
530	                  </svg>
531	                </button>
532	              </div>
533	            );
534	          })}
535	
536	          {/* "+" add-a-server picker */}
537	          {!minimized && (
538	            <div className="relative flex-none">
539	              <IconBtn onClick={togglePicker} label="Connect another server">
540	                <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
541	                  <path d="M12 5v14M5 12h14" />
542	                </svg>
543	              </IconBtn>
544	              {pickerOpen && (
545	                <div className="absolute left-0 top-9 z-10 w-64 overflow-hidden rounded-xl border border-white/10 bg-navy-900 shadow-2xl shadow-black/50">
546	                  <p className="border-b border-white/[0.06] px-3 py-2 text-[11px] font-semibold uppercase tracking-wider text-slate-500">
547	                    Open another server
548	                  </p>
549	                  <div className="max-h-56 overflow-y-auto py-1">
550	                    {pickerLoading ? (
551	                      <p className="px-3 py-3 text-xs text-slate-400">Loading…</p>
552	                    ) : pickerError ? (
553	                      <p className="px-3 py-3 text-xs text-red-300">{pickerError}</p>
554	                    ) : pickable.length === 0 ? (
555	                      <p className="px-3 py-3 text-xs text-slate-400">
556	                        No other running servers.
557	                      </p>
558	                    ) : (
559	                      pickable.map((s) => (
560	                        <button
561	                          key={s.id}
562	                          onClick={() => {
563	                            openSession(s);
564	                            setPickerOpen(false);
565	                          }}
566	                          className="flex w-full items-center gap-2 px-3 py-2 text-left text-xs text-slate-200 hover:bg-white/[0.06]"
567	                        >
568	                          <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8">
569	                            <rect x="3" y="4" width="18" height="7" rx="2" />
570	                            <rect x="3" y="13" width="18" height="7" rx="2" />
571	                          </svg>
572	                          <span className="truncate">{s.hostname}</span>
573	                        </button>
574	                      ))
575	                    )}
576	                  </div>
577	                </div>
578	              )}
579	            </div>
580	          )}
581	        </div>
582	
583	        {/* Right controls */}
584	        <div className="flex flex-none items-center gap-0.5">
585	          {minimized ? (
586	            <IconBtn onClick={restore} label="Expand terminal">
587	              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
588	                <path d="M15 3h6v6M9 21H3v-6M21 3l-7 7M3 21l7-7" />
589	              </svg>
590	            </IconBtn>
591	          ) : (
592	            <IconBtn onClick={minimize} label="Minimize terminal">
593	              <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
594	                <path d="M5 12h14" />
595	              </svg>
596	            </IconBtn>
597	          )}
598	          <IconBtn onClick={close} label="Close terminal dock">
599	            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
600	              <path d="M18 6 6 18M6 6l12 12" />
601	            </svg>
602	          </IconBtn>
603	        </div>
604	      </div>
605	
606	      {/* Terminal surface — every session container lives here at once; only the
607	          active one is shown. This subtree keeps the SAME nodes across
608	          minimize↔restore so xterm/socket are never recreated. */}
609	      <div className="relative min-h-0 flex-1 bg-[#0a0e1a] p-1.5">
610	        {sessions.map((s) => (
611	          <div
612	            key={s.id}
613	            ref={(el) => attach(s.id, el)}
614	            className="absolute inset-1.5"
615	            style={{ display: s.id === activeId ? "block" : "none" }}
616	          />
617	        ))}
618	      </div>
619	
620	      {/* Reconnect strip for the active session when its socket dropped. */}
621	      {activeMeta && (activeMeta.status === "closed" || activeMeta.status === "error") && (
622	        <div className="flex flex-none items-center gap-3 border-t border-white/[0.06] bg-white/[0.02] px-3 py-1.5 text-xs">
623	          <span className={activeMeta.status === "error" ? "text-red-300" : "text-slate-400"}>
624	            {errors[activeMeta.id] || (activeMeta.status === "error" ? "Error" : "Disconnected")}
625	          </span>
626	          <button
627	            onClick={() => reconnect(activeMeta.id)}
628	            className="ml-auto rounded-lg border border-white/10 bg-white/5 px-2.5 py-1 font-semibold text-slate-200 hover:bg-white/10"
629	          >
630	            Reconnect
631	          </button>
632	        </div>
633	      )}
634	    </div>
635	  );
636	}

