141: export async function login(
142:   prev: any,
143:   formData: FormData,
144: ): Promise<{ error?: string; needs2fa?: boolean }> {
145:   const parsed = credsSchema.safeParse({
146:     email: formData.get("email"),
147:     password: formData.get("password"),
148:   });
149:   if (!parsed.success) return { error: "Invalid email or password." };
150: 
151:   // App-level throttle per email+IP over a 15 min window. The max-attempts cap is
152:   // admin-configurable (`login_ratelimit_max`, default 10) rather than hardcoded.
153:   const hdrs = await headers();
154:   const ip = (hdrs.get("x-forwarded-for") ?? "").split(",")[0]?.trim() || "unknown";
155:   const rlId = `${parsed.data.email}:${ip}`;
156:   const maxAttempts = Math.max(1, await getSettingInt("login_ratelimit_max", 10));
157:   const rl = checkRateLimit(`login:${rlId}`, { max: maxAttempts, windowMs: 15 * 60 * 1000 });
158:   if (!rl.ok) return { error: `Too many attempts. Try again in ${rl.retryAfterSec}s.` };
159: 
160:   const user = await db.user.findUnique({ where: { email: parsed.data.email } });
161:   if (!user || !(await bcrypt.compare(parsed.data.password, user.passwordHash))) {
162:     return { error: "Invalid email or password." };
163:   }
164:   if (user.suspended) return { error: "This account is suspended." };
165: 
166:   // Two-factor challenge, if enabled on the account.
167:   if (user.totpEnabled) {
168:     const code = String(formData.get("code") ?? "").trim();
169:     if (!code) return { error: "Enter your 2FA code to continue.", needs2fa: true };
170:     if (!(await verifyTotpForUser(user.id, code))) {
171:       return { error: "Invalid 2FA code.", needs2fa: true };
172:     }
173:   }
174: 
175:   resetRateLimit(`login:${rlId}`);
176:   await audit(user.id, "user.login");
177:   await createSession(user.id);
178:   redirect(user.role === "ADMIN" ? "/admin" : "/dashboard");
179: }
